import { PlaneGeometry, Mesh, Group, MeshBasicNodeMaterial, Color } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // --- Plane with texture ---
  const geometry = new THREE.PlaneGeometry(4, 2.5);
  const material = new MeshBasicNodeMaterial({
    color: new Color(config.colors?.surface || '#0b0b10'),
    transparent: true,
  });
  const plane = new THREE.Mesh(geometry, material);
  plane.position.set(0, 0, 0); // relative to group
  group.add(plane);

  // Load texture async
  let textureDispose = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
      textureDispose = () => tex.dispose();
    }).catch(() => {});
  }

  // --- Text content ---
  const textContent = config.textContent?.[0] || config.intent?.visualSpec?.textContent?.[0];
  if (textContent && textContent.text) {
    const textNode = ctx.fontAtlas.createText(textContent.text, {
      fontSize: 0.34, // headline scene-unit height as per design tokens
      color: config.colors?.paper || '#e8ecf2',
      align: 'center',
      letterSpacingPx: 0.05, // match spec for display text
    });
    textNode.position.set(0, 0, 0.01); // slightly in front of plane
    group.add(textNode);
  }

  // Set userData for cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (textureDispose) textureDispose();
    // No GSAP timelines to kill
  };

  return group;
}
